  j jsonb := $json${"year": "1446 هـ", "target_year": "1447 هـ", "program": {"college": "كلية الاعمال", "department": "قسم معلوماتية الأعمال", "name": "ماجستير نظم المعلومات الإدارية"}, "intro": "انطلاقا من كون التعليم الاستثمار الأكبر في رأس المال البشري والمورد الأساسي للتنمية  وتلبية لاحتياجات المجتمع فقد حرصت إدارة برنامج الماجستير في نظم المعلومات الإدارية على وضع الخطوط العامة التي تقوم عليها إدارة البرنامج بوضع خطة تشغيلية  تتضمن أهداف تشغيلية واقعية وغير مستحيلة, قريبة المدى, قابلة للقياس, تتوافق مع طموحات جميع الأطراف المعنية كما تراعي الفترة الزمنية للخطة المحددة بعام دراسي, بما يهيئ الفرص لتجسير فجوات الأداء سواء وفق مسار تبادلي يرتكز على تناغم الطموحات مع الإمكانات والموارد او مسار تحويلي جوهره رفع كفاء الأداء للوصول إلى الأهداف والغايات وهدف البرنامج الأول و الرئيسي من الخطة التشغيلية هو تحديد ماذا يجب أن يتم تنفيذه لتحقيق الأهداف التشغيلية للبرنامج والمساهمة في تحقيق الأهداف الاستراتيجية للكلية وبناء على ذلك فقد تم وضع المبادرات والأنشطة التي تساهم في تحقيق الأهداف والتي تقاس وفقا لمؤشرات الأداء الرئيسة الصادرة من الهيئة الوطنية للتقويم والاعتماد الأكاديمي NCAAA ومؤشرات أداء البرنامج الفرعية التي نم وضعها بناء على الانشطة والمبادرات المحددة والتي يتم قياسها سنويا ويستفيد البرنامج من التغذية الراجعة لتحسين الاداء.", "missions": {"university": "بيئة اكاديمية محفزة لإنتاج المعرفة وتطبيقها، والبحث والابتكار، وتعزيز المسؤولية المجتمعية، والاسهام في تحقيق التنمية المستدامة بالاستثمار الأمثل لقدراتنا ومواردنا", "college": "توفير بيئة تعليمية محفزة لخلق المعرفة العلمية وتطبيقاتها العملية في قطاعات الاعمال، والبحث العلمي، وتعزيز الالتزام المجتمعي، والمساهمة في تحقيق النمو المستدام من خلال الاستثمار الأمثل لكفاءات وموارد الكلية", "department": "تهيئة بيئة تعليمية وبحثية محفّزة لإعداد خريجين مؤهلين بمهارات تقنية عالية في مجال نظم المعلومات الإدارية، وتعزيز الشراكات الفاعلة مع قطاعات الأعمال محليًا وإقليميًا ودوليًا، والمساهمة في تطوير المجتمع وتحقيق التنمية المستدامة من خلال استثمار المعرفة والابتكار", "program": "إعداد كوادر مهنية متقدمة في مجال نظم المعلومات ال