"kpis": ["KPI-PG-12|النسبة المئوية للطلاب الدبن نشروا بحوثهم في مجلات علمية محكمة الى اجمالي عدد الطلاب في البرنامج خلال السنة", "KPI-PG-12|النسبة المئوية للطلاب الذين قدموا أوراق علمية في مؤتمرات الى اجمالي عدد الطلاب في البرنامج خلال السنة", "KPI-PG-27|نسبة أعضاء هيئة التدريس المشاركين في الدوارات التدريبية المتعلقة بالبحث العلمي", "KPI-PG-29|نسبة الطلاب المستفيدين من الدوارات التدريبية المتعلقة بالبحث العلمي", "KPI-PG-25|رضا المستفيدين عن المرافق والتجهيزات البحثية", "KPI-PG-3|تقييم الطالب لجودة الإشراف العلمي"]}]}, {"text": "تنمية العلاقات الاستراتيجية المتوائمة مع أولويات البحث العلمي", "activities": [{"text": "برنامج شارك", "executor": "لجنة الدراسات العليا والبحث العلمي بالتعاون مع وحدة التدريب والشهادات الاحترافية وإدارة النشر العلمي", "budget": "موازنات مالية مخصصة للدورات", "kpis": ["KPI-PG-30|الدورات والفعاليات المقامة المتعلقة بالبحث العلمي"]}, {"text": "الدورات التدريبية في مجال البحث العلمي والنشر في المجالات المختلفة", "executor": "لجنة الدراسات العليا والبحث العلمي مع وحدة التدريب والشهادات الاحترافية", "budget": "موازنات مالية مخصصة للدورات", "kpis": ["KPI-PG-30|الدورات والفعاليات المقامة المتعلقة بالبحث العلمي"]}]}, {"text": "توجيه اولويات البحث العلمي لخدمة قضايا المجتمع", "activities": [{"text": "الدورات التدريبية في مجال البحث العلمي لتوجيه الابحاث لخدمة قضايا المجتمع", "executor": "لجنة الدراسات العليا والبحث العلمي ولجنة خدمة المجتمع بالتعاون مع وحدة التدريب والشهادات الاحترافية", "budget": "موازنات مالية مخصصة للدورات", "kpis": ["KPI-PG-31|رضا المستفيدين عن الخدمة المجتمعية"]}]}]}, {"text": "تفعيل الدور المجتمعي للبرنامج من خلال تقديم حلول تقنية تسهم في معالجة التحديات التنموية وتحقيق التكامل مع مؤسسات المجتمع", "aligns": {"university": [2], "college": [2], "department": [2, 5]}, "initiatives": [{"text": "تحفيز الاعمال التطوعية لمنسوبي الكلية", "activities": [{"text": "تحليل الوضع الراهن لأنشطة المشاركة المجتمعية التي يجريها البرنامج", "executor": "لجنة خدمة المجتمع", "budget": "المخصصات المالية من عمادة خدمة المجتمع والتعليم المستمر", "kpis": ["KPI-PG-31|رضا المستفيدين عن الخدمات المجتمعية", "KPI-PG-32|النسبة المئوية لمنسوبي البرنامج المشاركين في الأنشطة المجتمعية", "KPI-PG-33|النسبة المئوية للمشاركات المجتمعية"]}]}]}]}$json$::jsonb;
  v_col uuid; v_dep uuid; v_prog uuid; v_plan uuid; v_goal uuid; v_init uuid; v_act uuid; v_ind uuid;
  g jsonb; i jsonb; a jsonb; k jsonb; v_key text;
  gi int := 0; ii int; ai int; ki int;
begin
  -- البرنامج (يُبحث عنه ثم يُنشأ عند الغياب)
  select id into v_prog from programs
    where degree = 'master' and name_ar ilike '%نظم المعلومات الإدارية%' limit 1;
  if v_prog is null then
    select id into v_dep from departments where name_ar ilike '%معلوماتية%' limit 1;
    if v_dep is null then
      select id into v_col from colleges where name_ar ilike '%الأعمال%' limit 1;
      if v_col is null then
        insert into colleges (name_ar) values (j->'program'->>'college') returning id into v_col;
      end if;
      insert into departments (college_id, name_ar) values (v_col, j->'program'->>'department') returning id into v_dep;
    end if;
    insert into programs (department_id, name_ar, degree, language)
      values (v_dep, j->'program'->>'name', 'master', 'ar') returning id into v_prog;
  end if;

  if exists (select 1 from op_plans where program_id = v_prog and year_label = j->>'year') then
    raise notice 'الخطة % موجودة مسبقًا لهذا البرنامج — لم يتغيّر شيء.', j->>'year';
    return;
  end if;

  insert into op_plans (program_id, year_label, target_year_label, intro, context, status)
  values (v_prog, j->>'year', j->>'target_year', j->>'intro',
          jsonb_build_object('missions', j->'missions', 'lists', j->'lists'), 'final')
  returning id into v_plan;

  create temp table if not exists _kpi_map (kkey text primary key, id uuid) on commit drop;
  delete from _kpi_map;

  -- مؤشرات الأداء + قيمها
  for k in select * from jsonb_array_elements(j->'kpis') loop
    select id into v_ind from indicators
      where program_id = v_prog and kind = 'kpi' and code = k->>'code' and name_ar = k->>'name' limit 1;
    if v_ind is null then
      insert into indicators (kind, code, name_ar, program_id, degree_level, measure_type, calc_method, direction)
      values ('kpi', k->>'code', k->>'name', v_prog, 'master', k->>'measure',
              nullif(k->>'calc', ''), k->>'direction')
      returning id into v_ind;
    end if;
    insert into _kpi_map values (k->>'key', v_ind);
    insert into op_kpi_values (plan_id, indicator_id, actual, benchmark, target, new_target)
    values (v_plan, v_ind, nullif(k->>'actual', ''), nullif(k->>'benchmark', ''),
            nullif(k->>'target', ''), nullif(k->>'new_target', ''))
    on conflict (plan_id, indicator_id) do nothing;
  end loop;

  -- الأهداف ← المبادرات ← الأنشطة ← ربط المؤشرات
  for g in select * from jsonb_array_elements(j->'goals') loop
    insert into op_goals (plan_id, position, text_ar, aligns)
    values (v_plan, gi, g->>'text', g->'aligns') returning id into v_goal;
    gi := gi + 1; ii := 0;
    for i in select * from jsonb_array_elements(g->'initiatives') loop
      insert into op_initiatives (goal_id, position, text_ar) values (v_goal, ii, i->>'text') returning id into v_init;
      ii := ii + 1; ai := 0;
      for a in select * from jsonb_array_elements(i->'activities') loop
        insert into op_activities (initiative_id, position, text_ar, executor, budget)
        values (v_init, ai, a->>'text', nullif(a->>'executor', ''), nullif(a->>'budget', '')) returning id into v_act;
        ai := ai + 1; ki := 0;
        for v_key in select jsonb_array_elements_text(a->'kpis') loop
          insert into op_activity_kpis (activity_id, indicator_id, position)
          select v_act, m.id, ki from _kpi_map m where m.kkey = v_key
          on conflict do nothing;
          ki := ki + 1;
        end loop;
      end loop;
    end loop;
  end loop;

  raise notice 'تم إنشاء الخطة % بـ % أهداف.', j->>'year', gi;
end
$seed$;
